tinymce.PluginManager.add('dbrepo', function (editor, url) {

  editor.addCommand("cmdDBRepo", function () {
    editor.windowManager.openUrl({
      title: "DBRepo",
      url: RS.withCacheVersion(url + "/dialog.html"),
      width: 1000,
      height: 600,
      buttons: [
        { type: "cancel", id: "close", name: "close", text: "Close" }
      ]
    });
  });

  editor.ui.registry.addButton('dbrepo', {
    icon: 'dbrepo',
    tooltip: 'DBRepo',
    onAction: function () {
      editor.execCommand("cmdDBRepo");
    }
  });
});
